function SettingsPanel({settings,onSave,onClose}){
  const [form,setForm]=useState({...settings,apiKey:''}),[error,setError]=useState('');const set=(key,value)=>setForm(f=>({...f,[key]:value}));
  return <Modal title="Settings & usage" wide onClose={onClose}><div className="running-version"><strong>Running v{settings.appVersion}</strong><span>{settings.appPath}</span></div><div className="settings-grid"><div><div className="eyebrow">CONNECTED SERVICES</div><h3>ElevenLabs</h3><p className="muted">Scribe v2 for captions. Two-stem separation for a backing track. Your key is encrypted by Windows and stays out of project files.</p><Field label={settings.hasKey?'API key · saved securely':'API key'}><input type="password" autoComplete="off" placeholder={settings.hasKey?'Leave blank to keep your key':'Paste your ElevenLabs API key'} value={form.apiKey} onChange={e=>set('apiKey',e.target.value)}/></Field>{settings.hasKey&&<label className="checkbox"><input type="checkbox" checked={!!form.deleteKey} onChange={e=>set('deleteKey',e.target.checked)}/> Remove saved API key</label>}
      <PricingFields form={form} setForm={setForm}/></div>
      <div><div className="eyebrow">LOCAL PROCESSING</div><h3>FFmpeg tools</h3><p className="muted">Leave these blank to use FFmpeg and FFprobe from PATH. Import, editing, and export run on your computer.</p>{[['ffmpegPath','FFmpeg executable'],['ffprobePath','FFprobe executable']].map(([key,label])=><Field key={key} label={label}><input placeholder={`C:\\ffmpeg\\bin\\${key==='ffmpegPath'?'ffmpeg':'ffprobe'}.exe`} value={form[key]} onChange={e=>set(key,e.target.value)}/></Field>)}<div className="note"><CircleHelp size={17}/><span>Only the selected scene’s audio is uploaded when you explicitly run an AI job. No full movies are uploaded.</span></div></div></div>
      <div className="usage-head"><h3>Transaction history</h3><span className="muted">{settings.jobs.length} requests · estimated usage {money(settings.jobs.filter(j=>j.status!=='cancelled').reduce((sum,j)=>sum+(j.estimatedUsd||0),0))} · {settings.jobs.filter(j=>j.estimatedUsd==null).length} unpriced</span></div><div className="usage-table"><table><thead><tr><th>When / scene</th><th>Operation</th><th>Duration</th><th>Usage estimate</th><th>Status</th></tr></thead><tbody>{settings.jobs.map(j=><tr key={j.id} title={`${j.message||''} Request ID: ${j.requestId||'not returned'}. Plan: ${j.pricingTier||'not recorded'}. Rate USD/min: ${j.rateUsdPerMinute??'not recorded'}. Actual USD: ${j.actualUsd??'not returned by provider'}`}><td>{j.scene}<small>{new Date(j.time).toLocaleString()}</small></td><td>{j.kind}</td><td>{time(j.seconds)}</td><td>{money(j.estimatedUsd)}{j.pricingBasis&&<small>{j.pricingBasis}</small>}</td><td><span className={`status-${j.status}`}>{j.status}</span></td></tr>)}</tbody></table>{!settings.jobs.length&&<p className="table-empty">No requests yet. Each AI job will appear here, including failed or unconfirmed requests.</p>}</div>
      {error&&<p className="error-text">{error}</p>}<footer><span className="muted">Provider invoices remain the source of truth.</span><Button className="primary" icon={Check} onClick={async()=>{try{await onSave(form);onClose();}catch(e){setError(e.message);}}}>Save settings</Button></footer></Modal>;
}

function BulkDialogue({lines,characters,busy,onAssign,onMerge,onPlay,onDuplicate}){
  const common=sharedCharacter(lines),[character,setCharacter]=useState(common??'');
  useEffect(()=>setCharacter(common??''),[common]);
  const start=Math.min(...lines.map(c=>c.start)),end=Math.max(...lines.map(c=>c.end)),seconds=round(end-start);
  const pending=character.trim()!==(common??'');
  const mergeIssue=common===null?'Assign one character to these lines before merging.':pending?'Apply the character change before merging.':seconds>=60?'A merged line must be shorter than 60 seconds.':null;
  return <><div className="eyebrow">EDIT DIALOGUE</div><h3 className="bulk-count">{lines.length} lines selected</h3>
    <Field label="Character for selected lines"><input list="bulk-characters" value={character} disabled={busy} onChange={e=>setCharacter(e.target.value)} placeholder={common===null?'Mixed characters':'e.g. Nut Vendor'} onKeyDown={e=>{if(e.key==='Enter'&&character.trim()&&pending){e.preventDefault();onAssign(character);}}}/><datalist id="bulk-characters">{characters.map(c=><option key={c} value={c}/>)}</datalist></Field>
    <Button icon={Check} disabled={busy||!character.trim()||!pending} onClick={()=>onAssign(character)}>Apply character to {lines.length} lines</Button>
    <div className="duplicate-actions"><Button icon={Copy} disabled={busy||pending} onClick={onDuplicate}>Duplicate selected lines</Button></div>
    <div className="divider"/><strong className="merge-label">Merged line preview</strong>
    <p className="merge-times">{start.toFixed(3)} → {end.toFixed(3)}<small>scene seconds · {seconds.toFixed(3)}s total</small></p>
    <p className="merge-caption">{lines.map(c=>c.caption.trim()).filter(Boolean).join(' ')||'No captions yet'}</p>
    <p className="muted small">Keeps the full range, including pauses. Other lines stay unchanged. Undo restores the separate lines.</p>
    {seconds>6&&seconds<60&&<p className="amber small">Under 6 seconds is recommended.</p>}
    {mergeIssue&&<p className="amber small">{mergeIssue}</p>}
    <div className="bulk-actions"><Button icon={Play} disabled={busy} onClick={()=>onPlay(start,end)}>Play selected range</Button><Button icon={Layers} className="primary" disabled={busy||!!mergeIssue} onClick={onMerge}>Merge lines</Button></div>
  </>;
}

